/**
 * @name Code injection via eval/exec/compile
 * @description Untrusted function parameters flowing to eval, exec or compile
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-params
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("eval").getACall() or
        call = API::builtin("exec").getACall() or
        call = API::builtin("compile").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CodeInjFlow = TaintTracking::Global<CodeInjConfig>;
import CodeInjFlow::PathGraph

from CodeInjFlow::PathNode source, CodeInjFlow::PathNode sink
where CodeInjFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "function parameter"

/**
 * @name Path traversal via file access
 * @description Untrusted function parameters flowing to file system path arguments
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-params
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTravConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTravFlow = TaintTracking::Global<PathTravConfig>;
import PathTravFlow::PathGraph

from PathTravFlow::PathNode source, PathTravFlow::PathNode sink
where PathTravFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "function parameter"
